CREATE TABLE approval_routes (route_id TEXT PRIMARY KEY, contract_id TEXT NOT NULL, route_version INTEGER NOT NULL CHECK(route_version >= 1), governing_office_id TEXT NOT NULL, initiator_person_id TEXT NOT NULL, initiator_person_name TEXT NOT NULL, requested_start_date TEXT NOT NULL, requested_end_date TEXT NOT NULL, benchmark_end_date TEXT NOT NULL, operating_calendar_code TEXT NOT NULL, proposed_execution_date TEXT NOT NULL, agreement_type TEXT NOT NULL, proposed_amount_usd INTEGER NOT NULL CHECK(proposed_amount_usd >= 0), blocker_count_snapshot INTEGER NOT NULL CHECK(blocker_count_snapshot >= 0), route_status TEXT NOT NULL CHECK(route_status IN ('DRAFT','INTAKE_BLOCKED','WAITING','IN_REVIEW','APPROVED','REJECTED','CANCELLED')), route_created_at TEXT NOT NULL, route_updated_at TEXT NOT NULL, intake_note TEXT, UNIQUE(contract_id, route_version));

CREATE TABLE approval_steps (approval_step_id TEXT PRIMARY KEY, route_id TEXT NOT NULL, step_sequence INTEGER NOT NULL CHECK(step_sequence > 0), reviewer_role TEXT NOT NULL CHECK(reviewer_role IN ('Contract Management Specialist','Procurement Review','Legal Counsel','Fiscal Review','Authorized Signatory')), assigned_person_id TEXT NOT NULL, assigned_person_name TEXT NOT NULL, authority_id TEXT, prerequisite_code TEXT, prerequisite_description TEXT, decision_status TEXT NOT NULL CHECK(decision_status IN ('NOT_STARTED','WAITING','IN_REVIEW','APPROVED','REJECTED','RETURNED','ABSTAINED','CONDITIONAL')), decision_at TEXT, due_at TEXT NOT NULL, condition_text TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(route_id) REFERENCES approval_routes(route_id), FOREIGN KEY(authority_id) REFERENCES signature_authorities(authority_id), UNIQUE(route_id, step_sequence));

CREATE TABLE signature_authorities (authority_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, person_id TEXT NOT NULL, person_name TEXT NOT NULL, authority_type TEXT NOT NULL, dollar_limit_usd INTEGER NOT NULL CHECK(dollar_limit_usd >= 0), effective_start TEXT NOT NULL, effective_end TEXT NOT NULL, delegation_status TEXT NOT NULL CHECK(delegation_status IN ('ACTIVE','EXPIRED','FUTURE','REVOKED')), delegation_note TEXT, CHECK(effective_end >= effective_start));
CREATE TABLE approval_decision_events (event_id TEXT PRIMARY KEY, approval_step_id TEXT NOT NULL, route_id TEXT NOT NULL, assigned_person_id TEXT NOT NULL, actor_person_id TEXT NOT NULL, previous_decision_status TEXT NOT NULL, decision_status TEXT NOT NULL, recorded_at TEXT NOT NULL, FOREIGN KEY(approval_step_id) REFERENCES approval_steps(approval_step_id), FOREIGN KEY(route_id) REFERENCES approval_routes(route_id));
